 seen=set(); objs=[]
 for r in range(R):
  for c in range(C):
   if G[r][c] and G[r][c]!=barrier and (r,c) not in seen:
    color=G[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
    while q:
     x,y=q.pop(); cells.append((x,y))
     for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
      if 0<=a<R and 0<=b<C and G[a][b]==color and (a,b) not in seen:
       seen.add((a,b)); q.append((a,b))
    objs.append((color,cells))
 if toward=='down':
  objs.sort(key=lambda o:max(r for r,c in o[1]),reverse=True); step=1; bound=lambda r:r<R-1
 else:
  objs.sort(key=lambda o:min(r for r,c in o[1])); step=-1; bound=lambda r:r>0
 settled=[]
 for col,cells in objs:
  while all(bound(r) and (r+step,c) not in {p for _,cs in settled for p in cs} for r,c in cells):
   cells=[(r+step,c) for r,c in cells]
